244	    /**
245	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
246	     * already reached this many owners is rejected as a conflict.
247	     */
248	    static final int MAX_OWNERS_PER_CITY = 50;
249	
250	    /**
251	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
252	     * already reached this many registrations is rejected as a rate-limit violation.
253	     */
254	    static final int MAX_OWNERS_PER_DAY = 100;
255	
256	    /**
257	     * Number of owners that must already have registered on a day before a new registration is
258	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
259	     * value, the new owner carries {@code bulkSignupWarning == true}.
260	     */
261	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
262	
263	    @Override
264	    @Transactional
265	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
266	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
267	            throw new DisposableEmailDomainException(owner.getEmail());
268	        }
269	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
270	        rejectIdentityCollision(owner);
271	        List<Owner> householdMembers = findHouseholdMembers(owner);
272	        if (!householdMembers.isEmpty() && !sharesHousehold) {
273	            throw new HouseholdDuplicateException(owner.getHouseholdId());
274	        }
275	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
276	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
277	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
278	        }
279	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
280	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
281	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
282	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
283	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
284	        }
285	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
286	        flagPossibleDuplicate(owner, householdMembers, sharesHousehold);
287	        owner.setNamesakeCount(countNamesakes(owner));
288	        owner.setHouseholdSize(householdMembers.size() + 1);
289	        owner.setCustomerCode(CustomerCodeGenerator.format(
290	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
291	            owner.getTelephone(), owner.getLastName()));
292	        ownerRepository.save(owner);
293	        ownerAuditLogger.ownerCreated(owner);
294	        return owner.getHouseholdId();
295	    }
