297	    /**
298	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
299	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
300	     * key component (normalized telephone, email and household identifier) is a duplicate.
301	     */
302	    private void rejectIdentityCollision(Owner owner) {
303	        String identityKey = OwnerIdentityKey.of(owner);
304	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
305	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
306	        if (collides) {
307	            throw new DuplicateOwnerException(identityKey);
308	        }
309	    }
