311	    /**
312	     * Flag the new owner as a possible (soft) duplicate of an existing household member carrying a
313	     * different telephone. The new owner is still created; {@code possibleDuplicate} is set to
314	     * whether such a match exists and {@code possibleDuplicateOf} to the matching owner's id (the
315	     * lowest when several match), or {@code null} when there is no match.
316	     *
317	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
318	     * member rather than a suspected duplicate, so it is never flagged.
319	     */
320	    private void flagPossibleDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
321	        Owner match = sharesHousehold ? null : householdMembers.stream()
322	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
323	            .min(Comparator.comparingInt(Owner::getId))
324	            .orElse(null);
325	        owner.setPossibleDuplicate(match != null);
326	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
327	    }
