331	    public void saveOwner(Owner owner) throws DataAccessException {
332	        ownerRepository.save(owner);
333	    }
334	
335	    /**
336	     * Count the owners that already exist sharing this owner's first name and last name, compared
337	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
338	     */
339	    private int countNamesakes(Owner owner) {
340	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
341	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
342	            .count();
343	    }
344	
345	    /**
346	     * Find the existing owners that already share this owner's household, i.e. that derive the same
347	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
348	     * has no household peers.
349	     */
350	    private List<Owner> findHouseholdMembers(Owner owner) {
351	        if (owner.getPostcode() == null) {
352	            return List.of();
353	        }
354	        String householdId = owner.getHouseholdId();
355	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
356	            .filter(existing -> householdId.equals(
357	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
358	            .toList();
359	    }
360	
361	    @Override
362	    @Transactional(readOnly = true)
363	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
364	        return ownerRepository.findByLastName(lastName);
365	    }
366	
367	    @Override
368	    @Transactional(readOnly = true)
369	    public Collection<Visit> findVisitsByPetId(int petId) {
370	        return visitRepository.findByPetId(petId);
371	    }
372	
373	    @Override
374	    @Transactional(readOnly = true)
375	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
376	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
377	    }
378	
379	    private <T> T findEntityById(Supplier<T> supplier) {
380	        try {
381	            return supplier.get();
382	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
383	            // Just ignore not found exceptions for Jdbc/Jpa realization
384	            return null;
385	        }
386	    }
387	
388	}
