238	    /**
239	     * Handles exception thrown by Bean Validation on controller methods parameters
240	     *
241	     * @param e The {@link MethodArgumentNotValidException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
244	     */
245	    @ExceptionHandler(MethodArgumentNotValidException.class)
246	    @ResponseBody
247	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
248	        HttpStatus status = HttpStatus.BAD_REQUEST;
249	        BindingErrorsResponse errors = new BindingErrorsResponse();
250	        BindingResult bindingResult = e.getBindingResult();
251	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
252	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
253	            .map(FieldError::getField)
254	            .distinct()
255	            .toList());
256	        if (bindingResult.hasErrors()) {
257	            errors.addAllErrors(bindingResult);
258	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
259	                .map(fieldError -> {
260	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
261	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
262	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
263	                        fieldError.getField(),
264	                        defaultMessage,
265	                        rejectedValue);
266	                    return new ValidationMessageDto(message)
267	                        .putAdditionalProperty("field", fieldError.getField())
268	                        .putAdditionalProperty("rejectedValue", rejectedValue)
269	                        .putAdditionalProperty("defaultMessage", defaultMessage);
270	                })
271	                .toList();
272	            logger.debug("Validation error at {} {}: {}",
273	                request.getMethod(),
274	                request.getRequestURI(),
275	                bindingResult.getFieldErrors());
276	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
277	            return ResponseEntity.status(status).body(detail);
278	        }
279	        return ResponseEntity.status(status).body(detail);
280	    }
281	
282	}
