18	
19	import java.util.Locale;
20	import java.util.Map;
21	import java.util.regex.Pattern;
22	
23	/**
24	 * Reduces a postal address to a single canonical form used both for storage/display and for
25	 * household comparison: leading/trailing whitespace is trimmed, internal runs of whitespace are
26	 * collapsed to a single space, the result is upper-cased, and common street-type abbreviations are
27	 * expanded to their full words. Because the stored value is already canonical, any two addresses
28	 * that differ only in casing, whitespace or abbreviation resolve to the same string.
29	 */
30	public final class AddressNormalizer {
31	
32	    /** Any run of whitespace, collapsed to a single space. */
33	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
34	
35	    /** Street-type abbreviations expanded (per whitespace-separated word) to their full form. */
36	    private static final Map<String, String> ABBREVIATIONS = Map.of(
37	        "ST", "STREET",
38	        "RD", "ROAD",
39	        "AVE", "AVENUE");
40	
41	    private AddressNormalizer() {
42	    }
43	
44	    /**
45	     * Normalize the given address.
46	     *
47	     * @param address the raw address (may be {@code null})
48	     * @return the trimmed, whitespace-collapsed, upper-cased address with common abbreviations
49	     * expanded, or {@code null} when {@code address} is {@code null}
50	     */
51	    public static String normalize(String address) {
52	        if (address == null) {
53	            return null;
54	        }
55	        String collapsed = WHITESPACE.matcher(address.strip()).replaceAll(" ").toUpperCase(Locale.ROOT);
56	        if (collapsed.isEmpty()) {
57	            return "";
58	        }
59	        String[] words = collapsed.split(" ");
60	        StringBuilder result = new StringBuilder(collapsed.length());
61	        for (int i = 0; i < words.length; i++) {
62	            if (i > 0) {
63	                result.append(' ');
64	            }
65	            result.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
66	        }
67	        return result.toString();
68	    }
69	}
