17	package org.springframework.samples.petclinic.util;
18	
19	/**
20	 * Builds and parses an owner's {@code customerCode}, a stable {@code "<REGION>-<HASH8>"} identity
21	 * where {@code REGION} is the owner's region and {@code HASH8} is the first eight upper-case hex
22	 * characters of SHA-256 over the normalized telephone concatenated with the last name.
23	 */
24	public final class CustomerCodeGenerator {
25	
26	    /** Separator between the region prefix and the hash suffix. */
27	    private static final String SEPARATOR = "-";
28	
29	    /** Number of upper-case hex characters kept from the digest. */
30	    private static final int HASH_LENGTH = 8;
31	
32	    private CustomerCodeGenerator() {
33	    }
34	
35	    /**
36	     * Format a customer code as {@code "<REGION>-<HASH8>"} (for example {@code "NSW-1A2B3C4D"}),
37	     * where {@code HASH8} is the first eight upper-case hex characters of
38	     * {@code SHA-256(normalizedTelephone + lastName)}.
39	     *
40	     * @param region              the owner's region
41	     * @param normalizedTelephone the owner's normalized (E.164) telephone
42	     * @param lastName            the owner's last name
43	     * @return the formatted customer code
44	     */
45	    public static String format(String region, String normalizedTelephone, String lastName) {
46	        return region + SEPARATOR + hash8(normalizedTelephone, lastName);
47	    }
48	
49	    /**
50	     * Extract the {@code REGION} prefix from a customer code produced by {@link #format}.
51	     *
52	     * @param customerCode the customer code, may be {@code null}
53	     * @return the region prefix, or {@code null} when the customer code is {@code null}
54	     */
55	    public static String region(String customerCode) {
56	        if (customerCode == null) {
57	            return null;
58	        }
59	        int separator = customerCode.indexOf(SEPARATOR);
60	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
61	    }
62	
63	    private static String hash8(String normalizedTelephone, String lastName) {
64	        String key = orEmpty(normalizedTelephone) + orEmpty(lastName);
65	        return Sha256.hex(key).substring(0, HASH_LENGTH).toUpperCase();
66	    }
67	
68	    private static String orEmpty(String value) {
69	        return value == null ? "" : value;
70	    }
71	}
