17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Locale;
20	import java.util.Set;
21	
22	/**
23	 * Recognizes email addresses whose domain belongs to a known disposable-email provider, so an
24	 * owner cannot register with a throw-away address.
25	 */
26	public final class DisposableEmailDomains {
27	
28	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
29	        "mailinator.com", "tempmail.com", "guerrillamail.com");
30	
31	    private DisposableEmailDomains() {
32	    }
33	
34	    /**
35	     * Whether the given email's domain is on the disposable-domain blocklist.
36	     *
37	     * @param email the email value (may be {@code null})
38	     * @return {@code true} when {@code email} has a domain listed as disposable, {@code false}
39	     * when it is {@code null}, has no domain part or the domain is not blocked
40	     */
41	    public static boolean isDisposable(String email) {
42	        if (email == null) {
43	            return false;
44	        }
45	        int at = email.lastIndexOf('@');
46	        if (at < 0) {
47	            return false;
48	        }
49	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
50	        return BLOCKED_DOMAINS.contains(domain);
51	    }
52	}
